def gen(rng):
    OPS = ['SET', 'CLEAR', 'TOGGLE']
    def fmt(qs):
        return str(len(qs)) + '\n' + '\n'.join(f'{o} {x} {i}' for o, x, i in qs)
    M = 2**32 - 1
    tests = [fmt([('SET', 0, 0)]), fmt([('CLEAR', 0, 31)]), fmt([('TOGGLE', M, 31)]), fmt([('SET', M, 31)]),
             fmt([('CLEAR', M, 0), ('CLEAR', M, 31)]), fmt([('SET', 0, 31), ('TOGGLE', 2**31, 31)]),
             fmt([(o, 0, i) for o in OPS for i in (0, 15, 31)])]
    for _ in range(8):
        tests.append(fmt([(rng.choice(OPS), rng.randint(0, 255), rng.randint(0, 9)) for _ in range(rng.randint(1, 10))]))
    for _ in range(5):
        tests.append(fmt([(rng.choice(OPS), rng.randint(0, M), rng.randint(0, 31)) for _ in range(rng.randint(1, 8))]))
    tests.append(fmt([(rng.choice(OPS), rng.randint(0, M), rng.randint(0, 31)) for _ in range(50000)]))
    tests.append(fmt([(rng.choice(OPS), rng.choice([0, M, rng.randint(0, M)]), rng.choice([0, 31, rng.randint(0, 31)])) for _ in range(50000)]))
    return tests

